const $=id=>document.getElementById(id),ctx=$('field').getContext('2d'),KEY='fantasy-battle-lab-v1';let battle=new Battle(),target='enemy-0',busy=false,cutEnabled=true,flash=null,lastFrame=0,animation=null,playbackSpeed=1;
function save(){try{localStorage.setItem(KEY,battle.save());$('save-status').textContent='자동 저장됨 · 이 브라우저';}catch{$('save-status').textContent='저장 공간 사용 불가';}}
function message(t){$('feedback').textContent=t;}
const spriteImage=typeof Image==='function'?new Image():null;if(spriteImage)spriteImage.src='assets/battle-pixels.png';
function animProgress(){return animation?Math.max(0,Math.min(1,(Date.now()-animation.start)/animation.duration)):1;}
function dodgePose(u){if(!animation)return 0;const active=(animation.type==='dodge'&&animation.actor===u.id)||(animation.type==='attack'&&animation.target===u.id&&u.dodge)||(animation.type==='miss'&&animation.evaded&&animation.target===u.id);return active?Math.sin(animProgress()*Math.PI):0;}
function dodgeOffset(u){const k=dodgePose(u);return{x:(u.team==='ally'?-1:1)*36*k,y:-16*k};}
function unitPoint(u){if(animation?.actor===u.id&&animation.type==='move'){const t=animProgress(),k=t*t*(3-2*t),a=point(animation.from),b=point(animation.to);return{x:a.x+(b.x-a.x)*k,y:a.y+(b.y-a.y)*k};}const p=point(u),evade=dodgeOffset(u);p.x+=evade.x;p.y+=evade.y;if(animation?.actor===u.id&&animation.type==='attack'){const t=battle.units.find(a=>a.id===animation.target);if(t){const q=point(t),k=Math.sin(animProgress()*Math.PI)*.32;return{x:p.x+(q.x-p.x)*k,y:p.y+(q.y-p.y)*k};}}if(animation?.target===u.id&&animation.type==='hit'){p.x+=Math.sin(animProgress()*Math.PI*5)*5*(1-animProgress());}return p;}
function caption(event){const actor=battle.units.find(u=>u.id===event.actor);$('narrator').textContent=(actor?.name||'전장')+' · '+({think:'상황 판단',dodge:'회피 동작',skill:'스킬 시전',move:'이동',attack:'공격 동작',hit:'타격 결과',tell:'공격 준비',guard:'경계',heal:'회복',end:'전투 종료'}[event.type]||'상황');$('narration-text').textContent=event.text;$('narration').hidden=false;}

function render(){const p=battle.units[0];$('round').textContent='ROUND '+String(battle.round).padStart(2,'0');$('phase').textContent=busy?'행동 재생 중':battle.status==='playing'?'행동 대기 · 시간 정지':'전투 종료';$('timer').textContent=busy?'진행 중':'결정 중';$('potions').textContent=battle.potions;const enemies=battle.living('enemy');if(!enemies.some(x=>x.id===target))target=enemies[0]?.id;const t=enemies.find(x=>x.id===target);$('target-name').textContent=t?'대상 · '+t.name:'전투 종료';$('intent').textContent=t?(t.windup?'⚠ 다음 적 차례에 공격합니다. ':'접근 거리 '+battle.distance(p,t)+' · ')+(battle.distance(p,t)>1?'공격 시 먼저 접근':'현재 공격 가능'):'새 전투로 다시 테스트할 수 있습니다.';$('units').replaceChildren();const allyGroup=document.createElement('div'),enemyGroup=document.createElement('div');allyGroup.className='ally-status-group';enemyGroup.className='enemy-status-group';$('units').append(allyGroup,enemyGroup);for(const u of battle.units){const b=document.createElement('button');b.className='unit '+u.team+(u.id===target?' selected':'');b.disabled=busy||u.hp<=0||u.team==='ally';b.setAttribute('aria-pressed',String(u.id===target));const name=document.createElement('b');name.textContent=u.name+(u.hp<=0?' · 쓰러짐':u.windup?' · 공격 준비':'');const bar=document.createElement('div');bar.className='bar';const fill=document.createElement('i');fill.style.width=u.hp/u.max*100+'%';fill.style.background=u.hp/u.max<=.25?'#f36f62':u.hp/u.max<=.5?'#e6b856':u.team==='ally'?'#7bda9b':'#e99175';bar.append(fill);const hp=document.createElement('span');hp.textContent=u.hp+'/'+u.max+(u.id==='taei'?' · MP '+p.mana:'');if(u.team==='ally'){name.textContent=u.name+(u.id==='taei'?' · PLAYER':' · 동료');const avatar=document.createElement('span');avatar.className='status-avatar '+u.kind;const content=document.createElement('div');content.className='status-content';const hpLabel=document.createElement('span');hpLabel.className='resource-label';hpLabel.textContent='HP  '+u.hp+' / '+u.max;content.append(name,hpLabel,bar);const mpLabel=document.createElement('span');mpLabel.className='resource-label mana-label';mpLabel.textContent=u.id==='taei'?'MP  '+u.mana+' / 24':'MP  미사용';const mpBar=document.createElement('div');mpBar.className='mana-bar';const mpFill=document.createElement('i');mpFill.style.width=u.id==='taei'?u.mana/24*100+'%':'0%';mpBar.append(mpFill);content.append(mpLabel,mpBar);b.append(avatar,content);}else b.append(name,bar,hp);b.onclick=()=>{target=u.id;render();};(u.team==='ally'?allyGroup:enemyGroup).append(b);}for(const b of document.querySelectorAll('#actions button'))b.disabled=busy||battle.status!=='playing';$('skills-open').disabled=busy||battle.status!=='playing';$('input').disabled=busy||battle.status!=='playing';document.querySelector('#command button').disabled=busy||battle.status!=='playing';$('reset').disabled=busy;$('load').disabled=busy;$('result').hidden=battle.status==='playing';$('result').textContent={won:'전투 승리 · 모든 적을 제압했습니다',lost:'전투 불능 · 새 전투에서 다시 시도하세요',fled:'도주 성공 · 전투에서 벗어났습니다'}[battle.status]||'';$('logs').replaceChildren();for(const l of battle.log.slice(-50)){const p=document.createElement('p');p.textContent=l;$('logs').append(p);}$('logs').scrollTop=$('logs').scrollHeight;syncSprites();}
const previousHP=new Map();
let view={width:960,height:600,dpr:1},camera={x:480,y:280,zoom:0.8};
function resizeField(){const field=$('field');view.width=Math.max(280,window.innerWidth||960);view.height=Math.max(360,window.innerHeight||600);view.dpr=Math.min(2,window.devicePixelRatio||1);field.width=Math.round(view.width*view.dpr);field.height=Math.round(view.height*view.dpr);const mobile=view.width<600;const controlsHeight=$('actions').parentElement?.getBoundingClientRect?.().height|| (mobile?260:220);const top=view.height<600?105:mobile?170:160,bottom=controlsHeight+28;const available=Math.max(140,view.height-top-bottom);camera.zoom=Math.min(1.05,(view.width-60)/1040,available/440);camera.x=view.width/2;camera.y=top+available/2;document.documentElement.style.setProperty('--controls-height',controlsHeight+'px');}
function point(u){return{x:(u.x-3)*100-(u.y-1)*72,y:(u.x-3)*34+(u.y-1)*66};}
function screenPoint(u){const p=point(u);return{x:camera.x+p.x*camera.zoom,y:camera.y+p.y*camera.zoom};}
function diamond(x,y,w,h,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-h/2);ctx.lineTo(x+w/2,y);ctx.lineTo(x,y+h/2);ctx.lineTo(x-w/2,y);ctx.closePath();ctx.fill();}
function ground(){rect(-2600,-2200,5200,4400,'#40573c');for(let gy=-15;gy<=15;gy++)for(let gx=-20;gx<=20;gx++){const x=gx*72+gy*72,y=gy*36-gx*36;const n=Math.abs((gx*17+gy*31)%11),path=Math.abs(gy-gx)<3;diamond(x,y,144,72,path?(n<4?'#777356':'#716e50'):(n<4?'#405a3b':n<8?'#48613e':'#4b633f'));if(n%3===0){rect(x+12,y,7,3,path?'#8a8463':'#6a7c4b');rect(x-19,y+8,4,4,path?'#5d6047':'#344f33');}}}
function tree(x,y){diamond(x,y+18,96,40,'#1b372b66');rect(x-6,y-28,12,48,'#4b4934');rect(x-8,y-8,6,28,'#383f30');diamond(x,y-48,112,76,'#213c30');diamond(x-14,y-64,92,62,'#2d4b35');diamond(x+17,y-57,80,58,'#345438');diamond(x-5,y-80,66,46,'#3e5e3c');rect(x-23,y-79,14,4,'#587348');}
resizeField();window.addEventListener?.('resize',()=>{resizeField();syncSprites();});
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function sprite(u,x,y,frame){
 if(spriteImage?.complete&&spriteImage.naturalWidth){const row={taei:0,dogyeom:1,goblin:2,slime:3,ves:4}[u.kind];if(row!==undefined){let col=0;if(animation?.actor===u.id){if(animation.type==='dodge')col=1;else if(animation.type==='move')col=Math.floor(animProgress()*6)%2;else if(animation.type==='attack')col=2;}if(dodgePose(u)>.1)col=1;const cw=spriteImage.naturalWidth/3,ch=spriteImage.naturalHeight/5;ctx.save();ctx.translate(Math.round(x),Math.round(y));const evade=dodgePose(u);if(evade){ctx.rotate((u.team==='ally'?-.17:.17)*evade);ctx.scale(1+.06*evade,1-.16*evade);}if(u.team==='enemy')ctx.scale(-1,1);if(u.hp<=0){ctx.globalAlpha=.35;ctx.rotate(-.7);}const bob=busy&&animation?.actor===u.id&&animation.type==='move'?Math.sin(animProgress()*Math.PI*6)*2:Math.sin(frame*2)*.7;ctx.drawImage(spriteImage,col*cw,row*ch,cw,ch,-43,-73+bob,86,86);if(u.guard){ctx.strokeStyle='#b4cad6';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-25,33,-1.1,1.1);ctx.stroke();}ctx.restore();return;}}
ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(2,2);const enemy=u.team==='enemy';if(!enemy)ctx.scale(-1,1);let bounce=busy?Math.sin(frame*9)*1.2:Math.floor(frame*2)%2;ctx.translate(0,bounce);if(u.hp<=0){ctx.globalAlpha=.2;ctx.rotate(-.8);}const skin=enemy?'#718751':'#d2b6a0',hair=u.kind==='dogyeom'?'#d1c9b8':'#252b2f';if(!enemy){rect(-5,-28,10,8,hair);rect(-4,-21,8,7,skin);rect(-5,-23,10,3,hair);rect(-5,-14,10,12,'#30383b');rect(-8,-14,4,5,'#737b7b');rect(4,-14,4,5,'#737b7b');rect(-8,-9,3,7,skin);rect(5,-9,3,7,skin);rect(-9,-5,4,6,'#7f8585');rect(5,-5,4,6,'#7f8585');if(u.kind==='dogyeom'){rect(-8,-10,3,1,'#343938');rect(5,-8,3,1,'#343938');}rect(-5,-2,4,10,'#343b40');rect(1,-2,4,10,'#343b40');rect(-6,7,5,3,'#57483e');rect(1,7,6,3,'#57483e');rect(-3,-19,2,1,'#c1c8c0');}
else if(u.kind==='slime'){rect(-10,-5,20,12,'#72a5a2');rect(-7,-10,15,10,'#87bfba');rect(-3,-14,8,7,'#a2cebd');rect(-5,-6,2,3,'#477b79');rect(3,-6,2,3,'#477b79');rect(-1,0,4,4,'#d3eac0');rect(-11,6,24,4,'#5b9290');}
else if(u.kind==='ves'){const f=Math.sin(frame*8)>0?0:4;rect(-6,-15,12,14,'#655c72');rect(-6,-25,4,12,'#84718b');rect(2,-25,4,12,'#84718b');rect(-18,-18+f,12,4,'#79657f');rect(-22,-15+f,16,6,'#60536e');rect(6,-18+f,12,4,'#79657f');rect(6,-15+f,16,6,'#60536e');rect(-5,-13,3,2,'#c4a269');rect(2,-13,3,2,'#c4a269');rect(-4,-4,2,7,'#776b72');rect(3,-4,2,7,'#776b72');}
else{rect(-6,-24,12,11,skin);rect(-11,-22,5,4,skin);rect(6,-22,5,4,skin);rect(-5,-13,10,12,'#65543c');rect(-8,-13,3,11,skin);rect(5,-13,3,11,skin);rect(-5,-1,4,10,skin);rect(2,-1,4,10,skin);rect(-5,8,5,3,'#565f3e');rect(2,8,6,3,'#565f3e');rect(-3,-20,2,2,'#cbb366');rect(2,-20,2,2,'#cbb366');rect(8,-20,3,22,'#846d4b');rect(6,-22,7,7,'#a18459');}
ctx.restore();}
function syncSprites(){const layer=$('actors-layer');if(!layer)return;layer.replaceChildren();for(const u of battle.units){const row={taei:0,dogyeom:1,goblin:2,slime:3,ves:4}[u.kind];if(row===undefined)continue;const p=screenPoint(u);if(u.kind==='ves')p.y-=32*camera.zoom;const el=document.createElement('div');el.className='world-unit'+(u.hp<=0?' fallen':'');el.id='actor-'+u.id;el.style.left=p.x+'px';el.style.top=p.y+'px';el.style.width=86*camera.zoom+'px';el.style.height=86*camera.zoom+'px';el.style.zIndex=String(Math.round(point(u).y+1000));const body=document.createElement('div');body.className='pixel-body';body.style.setProperty('--row',(row*25)+'%');body.style.backgroundPosition='0% '+row*25+'%';if(u.team==='enemy')body.style.transform='scaleX(-1)';el.append(body);
const hp=document.createElement('div');hp.className='world-status'+(u.id===target?' focused':'')+(u.team==='ally'?' friendly':' hostile');hp.style.top=(-86*camera.zoom*.85-34)+'px';const title=document.createElement('span');title.className='world-name';title.textContent=u.name+(u.windup?' !':'');const track=document.createElement('div');track.className='world-hp';track.setAttribute('role','meter');track.setAttribute('aria-label',u.name+' 체력');track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax',String(u.max));track.setAttribute('aria-valuenow',String(u.hp));const ratio=u.hp/u.max;const old=previousHP.get(u.id)??u.hp;const lag=document.createElement('i');lag.className='hp-lag';lag.style.width=Math.max(old,u.hp)/u.max*100+'%';const fill=document.createElement('i');fill.className='hp-fill';fill.style.width=ratio*100+'%';fill.style.background=ratio<=.25?'#f36f62':ratio<=.5?'#e6b856':u.team==='ally'?'#7bda9b':'#e99175';track.append(lag,fill);const number=document.createElement('span');number.className='world-hp-value';number.textContent=u.hp+' / '+u.max;hp.append(title,track,number);el.append(hp);if(u.guard)el.classList.add('guarding');if(u.hp<old){el.classList.add('just-hit');setTimeout(()=>{lag.style.width=ratio*100+'%';},700);}previousHP.set(u.id,u.hp);layer.append(el);}}
function animateUnit(event,duration,forceActor=false){if(!forceActor&&event.type==='attack'&&battle.units.find(u=>u.id===event.target)?.dodge)animateUnit(event,duration,true);const id=forceActor?event.actor:event.type==='attack'&&battle.units.find(u=>u.id===event.target)?.dodge?event.target:event.type==='miss'&&event.evaded?event.target:event.actor;const u=battle.units.find(u=>u.id===id),el=$('actor-'+id);if(!u||!el)return;const body=el.firstElementChild;let keys=null;
 if(event.type==='move'){const a=point(event.from),b=point(event.to);keys=[{transform:'translate(0px,0px)'},{transform:'translate('+((b.x-a.x)*camera.zoom)+'px,'+((b.y-a.y)*camera.zoom)+'px)'}];el.classList.add('walking');}
 else if(event.type==='dodge'||(event.type==='attack'&&id===event.target)||(event.type==='miss'&&event.evaded)){const direction=u.team==='ally'?-1:1;keys=[{transform:'translate(0px,0px) rotate(0deg)'},{offset:.45,transform:'translate('+(direction*42*camera.zoom)+'px,'+(-18*camera.zoom)+'px) rotate('+(direction*12)+'deg)'},{offset:.7,transform:'translate('+(direction*36*camera.zoom)+'px,'+(-10*camera.zoom)+'px) rotate('+(direction*8)+'deg)'},{transform:'translate(0px,0px) rotate(0deg)'}];body.style.backgroundPosition='50% '+body.style.getPropertyValue('--row');}
 else if(event.type==='guard'){keys=[{transform:'translate(0px,0px)'},{offset:.35,transform:'translate(-5px,3px) scale(1.08,.88)'},{offset:.8,transform:'translate(-5px,3px) scale(1.08,.88)'},{transform:'translate(0px,0px)'}];el.classList.add('guarding');body.style.backgroundPosition='50% '+body.style.getPropertyValue('--row');}
 else if(event.type==='skill'){keys=[{transform:'translate(0px,0px)'},{offset:.5,transform:'translate(-10px,3px) scale(1.08,.92)'},{transform:'translate(0px,0px)'}];el.classList.add('charging');}
 else if(event.type==='attack'){el.classList.add('striking');const t=battle.units.find(a=>a.id===event.target);if(t){const a=point(u),b=point(t),x=(b.x-a.x)*camera.zoom*.55,y=(b.y-a.y)*camera.zoom*.55;keys=[{transform:'translate(0px,0px)'},{offset:.5,transform:'translate('+x+'px,'+y+'px)'},{transform:'translate(0px,0px)'}];body.style.backgroundPosition='100% '+body.style.getPropertyValue('--row');}}
 if(keys&&typeof el.animate==='function')el.animate(keys,{duration,easing:'ease-in-out',fill:event.type==='move'?'forwards':'none'});else if(keys){el.style.transition='transform '+duration+'ms ease-in-out';void el.offsetWidth;requestAnimationFrame(()=>{el.style.transform=keys[event.type==='move'?keys.length-1:1].transform;});}
}
function draw(ms){const f=ms/1000;ctx.setTransform(view.dpr,0,0,view.dpr,0,0);ctx.imageSmoothingEnabled=false;rect(0,0,view.width,view.height,'#40573c');ctx.save();ctx.translate(camera.x,camera.y);ctx.scale(camera.zoom,camera.zoom);ground();if(animation?.type==='move'){const a=point(animation.from),b=point(animation.to);ctx.strokeStyle='#e6d3a2';ctx.lineWidth=2/camera.zoom;ctx.setLineDash([6/camera.zoom,5/camera.zoom]);ctx.beginPath();ctx.moveTo(a.x,a.y+10);ctx.lineTo(b.x,b.y+10);ctx.stroke();ctx.setLineDash([]);diamond(b.x,b.y+10,28,14,'#e5cb8e80');}
for(let y=0;y<3;y++)for(let x=0;x<7;x++){const p=point({x,y});diamond(p.x,p.y,126,65,(x+y)%2?'#bbbc8620':'#b9ba8610');}
const decor=[[-700,-300],[-510,-260],[-300,-340],[-40,-330],[240,-300],[500,-210],[670,-120],[-770,70],[-590,140],[700,210],[-460,340],[370,380],[610,350]];
const drawables=[...decor.map(([x,y])=>({depth:y,tree:true,x,y})),...battle.units.map(u=>({depth:unitPoint(u).y,unit:u}))].sort((a,b)=>a.depth-b.depth);
for(const item of drawables){if(item.tree){tree(item.x,item.y);continue;}const u=item.unit,p=unitPoint(u),air=u.kind==='ves'?32:0;ctx.fillStyle='#142b2465';ctx.beginPath();ctx.ellipse(p.x,p.y+10,18,8,0,0,Math.PI*2);ctx.fill();if(u.id===target&&u.hp>0){ctx.strokeStyle='#e7cc88';ctx.lineWidth=2/camera.zoom;ctx.beginPath();ctx.ellipse(p.x,p.y+10,25,12,0,0,Math.PI*2);ctx.stroke();}if(!$('actors-layer'))sprite(u,p.x,p.y-air,f);}
ctx.restore();ctx.font='11px sans-serif';ctx.textAlign='center';for(const u of battle.units){if(u.hp<=0)continue;const wp=unitPoint(u),p={x:camera.x+wp.x*camera.zoom,y:camera.y+wp.y*camera.zoom},air=u.kind==='ves'?32*camera.zoom:0,head=77*camera.zoom;if(u.windup){ctx.fillStyle='#ffce82';ctx.font='bold 17px sans-serif';ctx.fillText('!',p.x,p.y-air-head-23);ctx.font='11px sans-serif';}if(flash?.target===u.id){ctx.font='bold 19px monospace';ctx.fillStyle='#ffc09d';ctx.fillText(flash.type==='hit'?'-'+flash.damage:flash.type==='miss'?'MISS':'',p.x,p.y-air-head-28);ctx.font='11px sans-serif';}}
requestAnimationFrame(draw);}
async function cut(kind,title){if(!cutEnabled||battle.seen.includes(kind))return;battle.seen.push(kind);const cell={goblin:[0,0],slime:[1,0]}[kind];if(!cell)return;$('cut-art').style.backgroundPosition=(cell[0]*100)+'% '+(cell[1]*100)+'%';$('cut-title').textContent=title;$('cutscene').showModal();save();await new Promise(resolve=>{$('cut-close').onclick=()=>$('cutscene').close();$('cutscene').addEventListener('close',resolve,{once:true});});}
async function act(action,skillId=null){if(busy||battle.status!=='playing')return;const before=Battle.restore(battle.save()),resolved=battle;let events;try{events=resolved.act(action,target,skillId);}catch(e){message(e.message);return;}busy=true;save();battle=before;
 try{render();for(const event of events){const reduced=window.matchMedia('(prefers-reduced-motion:reduce)').matches;const durations={skill:1000,guard:850,think:900,dodge:950,move:1200,attack:600,hit:650,tell:700,down:600,end:700,heal:700};const essential=['move','dodge'].includes(event.type);const duration=(reduced&&!essential?180:durations[event.type]||500)/playbackSpeed;flash=event;animation={...event,start:Date.now(),duration};caption(event);message(event.text);
 // Windup and movement are shown BEFORE committing that event's visible snapshot.
 if(!['move','attack','think'].includes(event.type)&&event.units){battle.units=event.units.map(u=>({...u}));battle.potions=event.potions;}
 render();animateUnit(event,duration);$('phase').textContent=event.type==='think'?'몬스터 판단 중':event.type==='move'?'이동 중':event.type==='attack'?'공격 동작':'행동 재생 중';
 await new Promise(r=>setTimeout(r,duration));
 if(event.units){battle.units=event.units.map(u=>({...u}));battle.potions=event.potions;}battle.log.push(event.text);render();}
 battle=resolved;flash=null;animation=null;render();const hit=events.find(e=>e.type==='hit'&&e.actor==='taei');const t=hit&&battle.units.find(u=>u.id===hit.target);if(t&&['goblin','slime'].includes(t.kind)&&(['heavy','skill'].includes(action)||battle.units[0].hp<=30)&&battle.units.filter(u=>u.team==='ally').length===1)await cut(t.kind,['heavy','skill'].includes(action)?'틈을 파고든 일격':'물러설 곳 없는 순간');
 }catch(error){message('연출 오류가 발생해 조작을 복구했습니다. '+error.message);}finally{battle=resolved;flash=null;animation=null;busy=false;save();render();}}
document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));$('command').onsubmit=e=>{e.preventDefault();const raw=$('input').value.trim(),action=battle.parse(raw);if(/스킬|기술/.test(raw)){openSkills();return;}if(!action){message('해석하지 못했어요. 공격·스킬·방어·회피·접근·후퇴·포션·도주 중 하나를 입력해 주세요.');return;}if(/그리고|다음에|동시에/.test(raw)){message('시제품에서는 한 번에 행동 하나만 입력해 주세요.');return;}if(action==='heavy'){openSkills();return;}if(/스킬|기술/.test(raw)){openSkills();return;}act(action);$('input').value='';};$('reset').onclick=()=>{if(busy)return;$('settings-dialog').close();battle=new Battle({kind:$('kind').value,count:Number($('count').value),partner:$('party').value==='duo'});target='enemy-0';previousHP.clear();save();render();message('새 전투를 시작했습니다. 적을 선택하고 행동하세요.');};$('load').onclick=()=>{try{battle=Battle.restore(localStorage.getItem(KEY));previousHP.clear();render();message('저장된 전투를 불러왔습니다.');}catch{message('불러올 수 있는 전투 저장이 없습니다.');}};$('cut-toggle').onclick=()=>{cutEnabled=!cutEnabled;$('cut-toggle').textContent='컷신 '+(cutEnabled?'켜짐':'꺼짐');$('cut-toggle').setAttribute('aria-pressed',String(cutEnabled));};$('help').onclick=()=>$('help-dialog').showModal();$('help-close').onclick=()=>$('help-dialog').close();$('field').onclick=e=>{if(busy)return;const r=$('field').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const found=battle.living('enemy').map(u=>{const p=screenPoint(u);if(u.kind==='ves')p.y-=32*camera.zoom;return{u,p,d:Math.hypot(x-p.x,y-(p.y-20*camera.zoom))};}).filter(a=>a.d<Math.max(24,45*camera.zoom)).sort((a,b)=>a.d-b.d)[0];if(found){target=found.u.id;render();}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='2'){openSkills();return;}const a={1:'attack',3:'guard',4:'dodge'}[e.key];if(a)act(a);});try{const raw=localStorage.getItem(KEY);if(raw)battle=Battle.restore(raw);}catch{message('저장을 읽지 못해 새 전투로 시작했습니다.');}render();requestAnimationFrame(draw);

$('logs-open').onclick=()=>$('logs-dialog').showModal();
$('logs-close').onclick=()=>$('logs-dialog').close();
$('settings-open').onclick=()=>$('settings-dialog').showModal();
$('settings-close').onclick=()=>$('settings-dialog').close();
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{message('이 브라우저에서는 전체 화면 전환을 지원하지 않습니다. 전장 화면은 그대로 이용할 수 있어요.');}};

$('speed').onclick=()=>{playbackSpeed=playbackSpeed===1?2:1;$('speed').textContent='연출 '+playbackSpeed+'×';};

function openSkills(){if(busy||battle.status!=='playing')return;$('skill-mana').textContent='현재 마나 '+battle.units[0].mana+' / 24';$('skill-list').replaceChildren();for(const skill of Battle.skills){const b=document.createElement('button');b.className='skill-option';b.disabled=battle.units[0].mana<skill.cost;const title=document.createElement('strong');title.textContent=skill.name;const cost=document.createElement('span');cost.className='skill-cost';cost.textContent='MP '+skill.cost;const desc=document.createElement('p');desc.textContent=skill.description+(b.disabled?' · 마나 부족':'');b.append(title,cost,desc);b.onclick=()=>{$('skills-dialog').close();act('skill',skill.id);};$('skill-list').append(b);}$('skills-dialog').showModal();}
$('skills-open').onclick=openSkills;$('skills-close').onclick=()=>$('skills-dialog').close();
